import re
from typing import Any

# Token types
TOK_INT = 'INT'
TOK_FLOAT = 'FLOAT'
TOK_IDENT = 'IDENT'
TOK_PLUS = '+'
TOK_MINUS = '-'
TOK_STAR = '*'
TOK_SLASH = '/'
TOK_PERCENT = '%'
TOK_CARET = '^'
TOK_LPAREN = '('
TOK_RPAREN = ')'
TOK_COMMA = ','
TOK_QUESTION = '?'
TOK_COLON = ':'
TOK_OR = '||'
TOK_AND = '&&'
TOK_EQ = '=='
TOK_NEQ = '!='
TOK_LT = '<'
TOK_LE = '<='
TOK_GT = '>'
TOK_GE = '>='
TOK_BANG = '!'
TOK_EOF = 'EOF'


def tokenize(expr: str) -> list[tuple[str, Any]]:
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        # Numbers
        if c.isdigit() or (c == '.' and i + 1 < n and expr[i + 1].isdigit()):
            # Decimal or integer
            j = i
            if c == '.':
                j = i + 1
                while j < n and expr[j].isdigit():
                    j += 1
                # Check for trailing dot like "2."
                # Actually, if we started with '.', it's like .5
                tokens.append((TOK_FLOAT, float(expr[i:j])))
                i = j
            else:
                while j < n and expr[j].isdigit():
                    j += 1
                # Check for decimal point
                if j < n and expr[j] == '.':
                    j += 1
                    while j < n and expr[j].isdigit():
                        j += 1
                    tokens.append((TOK_FLOAT, float(expr[i:j])))
                else:
                    tokens.append((TOK_INT, int(expr[i:j])))
                i = j
            continue
        # Identifiers
        if c.isalpha() or c == '_':
            j = i
            while j < n and (expr[j].isalnum() or expr[j] == '_'):
                j += 1
            tokens.append((TOK_IDENT, expr[i:j]))
            i = j
            continue
        # Two-char operators
        if i + 1 < n:
            two = expr[i:i + 2]
            if two == '||':
                tokens.append((TOK_OR, '||'))
                i += 2
                continue
            if two == '&&':
                tokens.append((TOK_AND, '&&'))
                i += 2
                continue
            if two == '==':
                tokens.append((TOK_EQ, '=='))
                i += 2
                continue
            if two == '!=':
                tokens.append((TOK_NEQ, '!='))
                i += 2
                continue
            if two == '<=':
                tokens.append((TOK_LE, '<='))
                i += 2
                continue
            if two == '>=':
                tokens.append((TOK_GE, '>='))
                i += 2
                continue
        # Single-char operators
        if c == '+':
            tokens.append((TOK_PLUS, '+'))
            i += 1
            continue
        if c == '-':
            tokens.append((TOK_MINUS, '-'))
            i += 1
            continue
        if c == '*':
            tokens.append((TOK_STAR, '*'))
            i += 1
            continue
        if c == '/':
            tokens.append((TOK_SLASH, '/'))
            i += 1
            continue
        if c == '%':
            tokens.append((TOK_PERCENT, '%'))
            i += 1
            continue
        if c == '^':
            tokens.append((TOK_CARET, '^'))
            i += 1
            continue
        if c == '(':
            tokens.append((TOK_LPAREN, '('))
            i += 1
            continue
        if c == ')':
            tokens.append((TOK_RPAREN, ')'))
            i += 1
            continue
        if c == ',':
            tokens.append((TOK_COMMA, ','))
            i += 1
            continue
        if c == '?':
            tokens.append((TOK_QUESTION, '?'))
            i += 1
            continue
        if c == ':':
            tokens.append((TOK_COLON, ':'))
            i += 1
            continue
        if c == '<':
            tokens.append((TOK_LT, '<'))
            i += 1
            continue
        if c == '>':
            tokens.append((TOK_GT, '>'))
            i += 1
            continue
        if c == '!':
            tokens.append((TOK_BANG, '!'))
            i += 1
            continue
        raise SyntaxError(f"Unexpected character: {c!r}")
    tokens.append((TOK_EOF, None))
    return tokens


class Parser:
    def __init__(self, tokens: list[tuple[str, Any]], env: dict[str, float] | None):
        self.tokens = tokens
        self.pos = 0
        self.env = env if env is not None else {}

    def peek(self) -> tuple[str, Any]:
        return self.tokens[self.pos]

    def advance(self) -> tuple[str, Any]:
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, tok_type: str) -> tuple[str, Any]:
        tok = self.peek()
        if tok[0] != tok_type:
            raise SyntaxError(f"Expected {tok_type}, got {tok[0]}")
        return self.advance()

    def parse(self) -> int | float:
        if self.peek()[0] == TOK_EOF:
            raise SyntaxError("Empty input")
        result = self.parse_conditional()
        if self.peek()[0] != TOK_EOF:
            raise SyntaxError(f"Trailing tokens: {self.peek()}")
        return result

    def parse_conditional(self) -> int | float:
        # a ? b : c, right-associative
        cond = self.parse_or()
        if self.peek()[0] == TOK_QUESTION:
            self.advance()
            then_branch = self.parse_conditional()  # right-associative
            self.expect(TOK_COLON)
            else_branch = self.parse_conditional()
            # Only evaluate the chosen branch
            if cond != 0:
                return then_branch
            else:
                return else_branch
        return cond

    def parse_or(self) -> int | float:
        left = self.parse_and()
        while self.peek()[0] == TOK_OR:
            self.advance()
            right = self.parse_and()
            left = 1 if (left != 0 or right != 0) else 0
        return left

    def parse_and(self) -> int | float:
        left = self.parse_comparison()
        while self.peek()[0] == TOK_AND:
            self.advance()
            right = self.parse_comparison()
            left = 1 if (left != 0 and right != 0) else 0
        return left

    def parse_comparison(self) -> int | float:
        left = self.parse_additive()
        if self.peek()[0] in (TOK_EQ, TOK_NEQ, TOK_LT, TOK_LE, TOK_GT, TOK_GE):
            op = self.advance()[0]
            right = self.parse_additive()
            if op == TOK_EQ:
                return 1 if left == right else 0
            elif op == TOK_NEQ:
                return 1 if left != right else 0
            elif op == TOK_LT:
                return 1 if left < right else 0
            elif op == TOK_LE:
                return 1 if left <= right else 0
            elif op == TOK_GT:
                return 1 if left > right else 0
            elif op == TOK_GE:
                return 1 if left >= right else 0
        # Check for non-associativity: if next token is another comparison, error
        if self.peek()[0] in (TOK_EQ, TOK_NEQ, TOK_LT, TOK_LE, TOK_GT, TOK_GE):
            raise SyntaxError("Non-associative comparison")
        return left

    def parse_additive(self) -> int | float:
        left = self.parse_multiplicative()
        while self.peek()[0] in (TOK_PLUS, TOK_MINUS):
            op = self.advance()[0]
            right = self.parse_multiplicative()
            if op == TOK_PLUS:
                left = left + right
            else:
                left = left - right
        return left

    def parse_multiplicative(self) -> int | float:
        left = self.parse_unary()
        while self.peek()[0] in (TOK_STAR, TOK_SLASH, TOK_PERCENT):
            op = self.advance()[0]
            right = self.parse_unary()
            if op == TOK_STAR:
                left = left * right
            elif op == TOK_SLASH:
                if right == 0:
                    raise ZeroDivisionError("Division by zero")
                if isinstance(left, int) and isinstance(right, int):
                    if left % right == 0:
                        left = left // right
                    else:
                        left = left / right
                else:
                    left = left / right
            elif op == TOK_PERCENT:
                if right == 0:
                    raise ZeroDivisionError("Modulo by zero")
                left = left % right
        return left

    def parse_unary(self) -> int | float:
        if self.peek()[0] in (TOK_MINUS, TOK_PLUS, TOK_BANG):
            op = self.advance()[0]
            operand = self.parse_unary()
            if op == TOK_MINUS:
                return -operand
            elif op == TOK_PLUS:
                return operand
            elif op == TOK_BANG:
                return 1 if operand == 0 else 0
        return self.parse_power()

    def parse_power(self) -> int | float:
        # ^ is right-associative, binds tighter than unary minus on its left
        # -2^2 is -4, 2^-1 is 0.5, 2^3^2 is 512
        base = self.parse_atom()
        if self.peek()[0] == TOK_CARET:
            self.advance()
            # Right-associative: parse the exponent as a unary expression
            # so that 2^-1 works
            exponent = self.parse_unary()
            return base ** exponent
        return base

    def parse_atom(self) -> int | float:
        tok = self.peek()
        if tok[0] == TOK_INT:
            self.advance()
            return tok[1]
        if tok[0] == TOK_FLOAT:
            self.advance()
            return tok[1]
        if tok[0] == TOK_IDENT:
            self.advance()
            name = tok[1]
            # Check for function call
            if self.peek()[0] == TOK_LPAREN:
                self.advance()  # consume '('
                args = []
                if self.peek()[0] != TOK_RPAREN:
                    args.append(self.parse_conditional())
                    while self.peek()[0] == TOK_COMMA:
                        self.advance()
                        args.append(self.parse_conditional())
                self.expect(TOK_RPAREN)
                if name == 'min':
                    if len(args) < 1:
                        raise SyntaxError("min requires at least 1 argument")
                    return min(args)
                elif name == 'max':
                    if len(args) < 1:
                        raise SyntaxError("max requires at least 1 argument")
                    return max(args)
                elif name == 'abs':
                    if len(args) != 1:
                        raise SyntaxError("abs requires exactly 1 argument")
                    return abs(args[0])
                else:
                    raise NameError(f"Unknown function: {name}")
            else:
                # Variable lookup
                if name not in self.env:
                    raise NameError(f"Unknown variable: {name}")
                return self.env[name]
        if tok[0] == TOK_LPAREN:
            self.advance()
            result = self.parse_conditional()
            self.expect(TOK_RPAREN)
            return result
        raise SyntaxError(f"Unexpected token: {tok}")


def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    tokens = tokenize(expr)
    parser = Parser(tokens, env)
    return parser.parse()
