import re
from functools import total_ordering


@total_ordering
class Version:
    def __init__(self, major, minor, patch, prerelease=None, build=None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease  # list of identifiers or None
        self.build = build  # list of identifiers or None

    def __repr__(self):
        s = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            s += "-" + ".".join(str(p) for p in self.prerelease)
        if self.build:
            s += "+" + ".".join(str(b) for b in self.build)
        return s

    def __eq__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major == other.major and
                self.minor == other.minor and
                self.patch == other.patch and
                self._prerelease_key() == other._prerelease_key())

    def __lt__(self, other):
        if not isinstance(other, Version):
            return NotImplemented
        if self.major != other.major:
            return self.major < other.major
        if self.minor != other.minor:
            return self.minor < other.minor
        if self.patch != other.patch:
            return self.patch < other.patch
        return self._prerelease_key() < other._prerelease_key()

    def _prerelease_key(self):
        if self.prerelease is None:
            return (1,)
        key = [0]
        for ident in self.prerelease:
            if isinstance(ident, int):
                key.append((0, ident, ""))
            else:
                key.append((1, 0, ident))
        return tuple(key)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch, self._prerelease_key()))


def parse(v: str) -> Version:
    if not isinstance(v, str):
        raise ValueError(f"Expected string, got {type(v)}")

    s = v.strip()
    if not s:
        raise ValueError("Empty version string")

    if s.startswith('v') or s.startswith('='):
        s = s[1:]

    pattern = r'^(\d+)\.(\d+)\.(\d+)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
    m = re.match(pattern, s)
    if not m:
        raise ValueError(f"Invalid version: {v}")

    major = int(m.group(1))
    minor = int(m.group(2))
    patch = int(m.group(3))

    if m.group(1) != str(major):
        raise ValueError(f"Leading zeros in major: {v}")
    if m.group(2) != str(minor):
        raise ValueError(f"Leading zeros in minor: {v}")
    if m.group(3) != str(patch):
        raise ValueError(f"Leading zeros in patch: {v}")

    prerelease = None
    if m.group(4):
        prerelease = []
        for ident in m.group(4).split('.'):
            if ident == '':
                raise ValueError(f"Empty prerelease identifier: {v}")
            if ident.isdigit():
                if len(ident) > 1 and ident[0] == '0':
                    raise ValueError(f"Leading zeros in numeric prerelease identifier: {v}")
                prerelease.append(int(ident))
            else:
                prerelease.append(ident)

    build = None
    if m.group(5):
        build = m.group(5).split('.')
        for ident in build:
            if ident == '':
                raise ValueError(f"Empty build identifier: {v}")

    return Version(major, minor, patch, prerelease, build)


def _parse_partial_version(s: str):
    s = s.strip()
