    pattern = r'^(\d+|X|x|\*)(?:\.(\d+|X|x|\*)(?:\.(\d+|X|x|\*)(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?)?)?$'
