        return (major, 0, 0, None, None, True, 1)

    minor = int(minor_str)
    if minor_str != str(minor):
        raise ValueError(f"Leading zeros in minor: {s}")

    if patch_str is None or patch_str in ('X', 'x', '*'):
        return (major, minor, 0, None, None, True, 2)

    patch = int(patch_str)
    if patch_str != str(patch):
        raise ValueError(f"Leading zeros in patch: {s}")

    prerelease = None
    if prerelease_str:
        prerelease = []
        for ident in prerelease_str.split('.'):
            if ident == '':
                raise ValueError(f"Empty prerelease identifier: {s}")
            if ident.isdigit():
