                    raise ValueError(f"Leading zeros in numeric prerelease identifier: {s}")
                prerelease.append(int(ident))
            else:
                prerelease.append(ident)

    build = None
    if build_str:
        build = build_str.split('.')
        for ident in build:
            if ident == '':
                raise ValueError(f"Empty build identifier: {s}")

    return (major, minor, patch, prerelease, build, False, 3)


