                    # We need to find the matching }
                    # The name is [A-Za-z_][A-Za-z0-9_]*
                    # Then optionally :- or - followed by default text
                    # The default text can contain nested ${...}
                    # We need to find the matching } considering nesting
                    depth = 1
                    start = k
                    while k < m and depth > 0:
                        if text[k] == '{':
                            depth += 1
                        elif text[k] == '}':
                            depth -= 1
                        k += 1
                    if depth != 0:
                        raise ValueError("Unterminated ${")
                    # The content is text[start:k-1]
                    content = text[start:k - 1]
                    # Parse the content
                    # Find the name
