                    if p < len(content) and (content[p].isalpha() or content[p] == '_'):
                        while p < len(content) and (content[p].isalnum() or content[p] == '_'):
                            p += 1
                        name = content[:p]
                        rest = content[p:]
                        if rest.startswith(':-'):
                            default_text = rest[2:]
                            # Expand the default text
                            expanded_default = expand(default_text, quoted)
                            val = env.get(name, '')
                            if val == '':
