def _resolve_type(tp: Any, cls: Any) -> Any:
    """Resolve a type annotation, handling string annotations."""
    if isinstance(tp, str):
        try:
            import sys
            import builtins
            ns = {
                'int': int,
                'float': float,
                'str': str,
                'bool': bool,
                'list': list,
                'dict': dict,
                'tuple': tuple,
                'Optional': typing.Optional,
                'Union': typing.Union,
                'Literal': typing.Literal,
                'None': type(None),
            }
            module = sys.modules.get(cls.__module__)
            if module:
                for name in dir(module):
                    obj = getattr(module, name)
                    if isinstance(obj, type) and dataclasses.is_dataclass(obj):
