    if [ ! -r "$FILE" ]; then
        echo "Cannot read file: $FILE" >&2
        exit 1
    fi
    exec < "$FILE"
fi

# Use awk to parse CSV and extract the column
# We need to handle:
# - Quoted fields with embedded delimiters, escaped quotes (""), and newlines
# - CRLF and LF line endings
# - Header row for column identification
# - #N for 1-based column index
# - Exact match for header name

# The awk script will:
# 1. Parse the CSV properly
# 2. Identify the column index from the header
# 3. Output the values (or compute summary)

# We'll pass the delimiter, column spec, and summary flag to awk
# The tricky part is handling multi-line quoted fields in awk.

# Strategy: Read the entire input, parse it character by character in awk.

awk -v delim="$DELIM" -v colspec="$COLUMN" -v summary="$SUMMARY" '
BEGIN {
    # State variables for CSV parsing
    in_quotes = 0
    field = ""
    fields = ""
    nfields = 0
    row = 0
    header_done = 0
    col_idx = -1
    count = 0
    sum = 0
    min_val = 0
    max_val = 0
    has_numeric = 0
    unterminated = 0
    output_buf = ""
    first_row = 1
}

function flush_field() {
    # Add the current field to the fields list
    if (nfields == 0) {
        fields = field
    } else {
        fields = fields SUBSEP field
    }
    nfields++
    field = ""
}

function flush_row() {
    # Process the current row
    row++
    if (row == 1) {
        # Header row: determine column index
        # Split fields by SUBSEP
        nf = split(fields, f, SUBSEP)
        if (colspec ~ /^#[0-9]+$/) {
            idx = substr(colspec, 2) + 0
            if (idx < 1 || idx > nf) {
                printf "Unknown column: %s\n", colspec > "/dev/stderr"
                exit 3
            }
            col_idx = idx
        } else {
            col_idx = -1
            for (i = 1; i <= nf; i++) {
                if (f[i] == colspec) {
                    col_idx = i
                    break
                }
            }
            if (col_idx == -1) {
                printf "Unknown column: %s\n", colspec > "/dev/stderr"
                exit 3
            }
        }
        header_done = 1
    } else {
        # Data row: extract the column value
        nf = split(fields, f, SUBSEP)
        if (col_idx <= nf) {
            val = f[col_idx]
        } else {
            val = ""
        }
        if (summary == 1) {
            # Check if numeric
            if (val ~ /^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)$/) {
                num = val + 0
                count++
                sum += num
                if (!has_numeric) {
                    min_val = num
                    max_val = num
                    has_numeric = 1
                } else {
                    if (num < min_val) min_val = num
                    if (num > max_val) max_val = num
                }
            }
        } else {
            # Replace embedded newlines with literal \n
            gsub(/\n/, "\\n", val)
            print val
        }
    }
    # Reset for next row
    fields = ""
    nfields = 0
    field = ""
}

{
    # Process each line of input
    line = $0
    # Remove trailing \r if present (handle CRLF)
    sub(/\r$/, "", line)

    # Process character by character
    len = length(line)
    for (i = 1; i <= len; i++) {
        c = substr(line, i, 1)
        if (in_quotes) {
            if (c == "\"") {
                # Check for escaped quote
                if (i < len && substr(line, i+1, 1) == "\"") {
                    field = field "\""
                    i++
                } else {
                    in_quotes = 0
                }
            } else {
                field = field c
            }
        } else {
            if (c == "\"") {
                in_quotes = 1
            } else if (c == delim) {
                flush_field()
            } else {
                field = field c
            }
        }
    }

    # End of line: if not in quotes, this is end of row
    if (!in_quotes) {
        flush_field()
        flush_row()
    }
    # If in_quotes, the field continues on next line (embedded newline)
    # We need to add a newline to the field
    if (in_quotes) {
        field = field "\n"
    }
}

END {
    # Check for unterminated quote
    if (in_quotes) {
        printf "Unterminated quote at end of input\n" > "/dev/stderr"
        exit 4
    }

    # If we have a pending field/row (should not happen if input ends with newline)
    # But handle case where last line has no trailing newline
    if (nfields > 0 || field != "") {
        flush_field()
        flush_row()
    }

    if (summary == 1) {
        if (count == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", count, sum, min_val, max_val
        }
    }
}
'
exit $?
