        if (summary == 1) {
            if (val ~ /^[+-]?([0-9]+(\.[0-9]*)?|\.[0-9]+)$/) {
                num = val + 0
                count++
                sum += num
                if (!has_numeric) {
                    min_val = num
                    max_val = num
                    has_numeric = 1
                } else {
                    if (num < min_val) min_val = num
                    if (num > max_val) max_val = num
                }
            }
        } else {
            gsub(/\n/, "\\n", val)
            print val
        }
    }
    pending_fields = ""
    pending_nfields = 0
    pending_field = ""
}

{
    line = $0
    sub(/\r$/, "", line)

    len = length(line)
    for (i = 1; i <= len; i++) {
        c = substr(line, i, 1)
        if (in_quotes) {
            if (c == "\"") {
                if (i < len && substr(line, i+1, 1) == "\"") {
                    pending_field = pending_field "\""
                    i++
                } else {
                    in_quotes = 0
                }
            } else {
                pending_field = pending_field c
            }
        } else {
            if (c == "\"") {
                in_quotes = 1
            } else if (c == delim) {
                flush_field()
            } else {
                pending_field = pending_field c
            }
        }
    }

    if (!in_quotes) {
        flush_field()
        process_row()
    } else {
        pending_field = pending_field "\n"
    }
}

END {
    if (in_quotes) {
        printf "Unterminated quote at end of input\n" > "/dev/stderr"
        exit 4
    }

    if (pending_nfields > 0 || pending_field != "") {
        flush_field()
        process_row()
    }

    if (summary == 1) {
        if (count == 0) {
            print "count=0"
        } else {
            printf "count=%d sum=%g min=%g max=%g\n", count, sum, min_val, max_val
        }
    }
}
'
exit $?
